 const before=JSON.stringify(tasks.map(t=>({id:t.id,prereqs:t.prereqs,inputs:t.inputs,role:t.role,refs:t.refs,modifications:t.modifications})));
 for(const t of tasks){
  const d=data.get(t.id);if(!d)throw Error('Missing consultant draft '+t.id);
  Object.assign(t,d,{languageStyle:'Business consultant; precise configuration instructions'});
  t.configurationRows??=[];t.steps??=[];
  if(/^IMP-5[1-8]$/.test(t.id)){
   t.scope+=' Create the approved definition, or update the same-purpose existing definition only when G08 identifies it. For an existing definition, update the specified fields, filters, grouping, visibility and generation/storage settings while retaining its record identity.';
  }
  t.rationale=({
   'Associate Consultant':'The fields, controls or basic access settings are defined and use established Intelex configuration. The more complex save and workflow rules are assigned separately.',
   'Senior Associate Consultant':'This assignment needs independent configuration judgment for conditional screens, calculations or standard workflow rules.',
   'Consultant':'The configuration connects related records or native functions; it requires care to preserve the intended source, result and workflow behavior.',
   'Senior Consultant':'The assignment coordinates completion, accepted evidence or related-record security and needs specialist judgment.'
  })[t.role]+' A separate Senior Consultant product build manager reviews the result.';
  if(t.id==='IMP-39')t.rationale+=' Initial save, completion and assignment suppression remain together because they produce one completed-correction result.';
  t.suppliedInputDescriptions=t.inputs.map(id=>({id,description:inputDescriptions[id]}));
  const blocks=[];
  if(t.inputs.length)blocks.push('Waiting for supplied inputs: '+t.inputs.map(id=>id+' — '+inputDescriptions[id]).join(' '));
  if(t.prereqs.length)blocks.push('Requires the configured outputs of '+t.prereqs.join(', ')+'.');
  if(t.upstreamInputs.length)blocks.push('Predecessors also depend on '+t.upstreamInputs.join(', ')+'.');
  t.blocked=blocks.join(' ')||'No missing supplied input or prerequisite is identified for this assignment. Task completion is not recorded by this plan.';
  for(const m of t.modifications){
   m.businessElement=m.element;
   m.businessBefore=m.before.replace(/; (?:field|record) ID [a-f0-9-]+/gi,'').replace(/; E\d+/g,'').replace(/IsRequired=true/g,'Mandatory at the underlying object level').replace(/IsRequired=false/g,'Optional at the underlying object level').replace(/IsReadOnly=true/g,'read-only').replace(/IsReadOnly=false/g,'field is not globally read-only').replace(/default TRUE/g,'default Yes').replace(/default FALSE/g,'default No').replace(/no field default exported/g,'no default shown in the package').replace(/native calculation exported/g,'existing calculation is included in the package');
   if(m.kind==='Field')m.businessChange=change.get(m.object+'.'+m.field);
   else if(m.element.startsWith('IsAuditEnabled'))m.businessChange='Change audit history from disabled to enabled on this existing Inspection object for changing review decisions, comments, actors and dates. Preserve unrelated object audit settings.';
   else m.businessChange=nativeChanges[m.evidence];
   if(!m.businessChange)throw Error('Missing business instruction '+t.id+' '+m.element);
  }
 }
 if(data.size!==tasks.length)throw Error('Unexpected consultant draft count');
 // Wording may change; configuration assignments and traceability may not.
 const after=JSON.stringify(tasks.map(t=>({id:t.id,prereqs:t.prereqs,inputs:t.inputs,role:t.role,refs:t.refs,modifications:t.modifications.map(({businessElement,businessBefore,businessChange,...original})=>original)})));
 if(before!==after)throw Error('Language revision changed configuration assignment boundaries');
 return {inputDescriptions,draftedTasks:data.size};
